if (typeof window !== 'undefined' && window.EM_TRANSLATIONS) {
  Object.keys(ELECTROMART_PAY_HUB_I18N).forEach(lang => {
    if (window.EM_TRANSLATIONS[lang]) {
      const src = ELECTROMART_PAY_HUB_I18N[lang] || {};
      const aliases = {
        electromart_pay_balance: src.pay_use_wallet_balance || src.pay_available_balance || "ElectroMart Pay Balance",
        pay_add_money_title: src.pay_add_money_heading || "Add Money to Balance",
        pay_add_money_sub: "Fast top-up using UPI, Credit/Debit Cards, or Net Banking",
        pay_upi_section_title: src.pay_virtual_upi_title || "ElectroMart Pay UPI",
        pay_upi_section_sub: src.pay_page_subtitle || "Virtual UPI ID linked directly to your store account",
        pay_statement_title: src.pay_passbook_title || "Passbook & Transaction History",
        pay_statement_sub: "Comprehensive audit trail of all credits, debits and cashback",
        pay_rewards_title: src.pay_cashback_rewards_title || "Cashback & Scratch Cards",
        pay_rewards_sub: "Guaranteed 5% cashback on every ElectroMart Pay order",
        pay_insufficient_warning: src.pay_insufficient_balance_msg || src.pay_insufficient_balance || "Insufficient balance. Please select an alternative payment method (e.g. UPI or Cards) or add money."
      };
      Object.assign(window.EM_TRANSLATIONS[lang], src, aliases);
    }
  });
}

