  deals_savings: 'deal_savings_label',
  select_prime_plan: 'choose_prime_plan',
  all_prime_benefits: 'prime_benefits_heading',
  savings_tracker_title: 'prime_savings_title',
  savings_tracker_desc: 'prime_savings_desc',
  change_plan: 'change_plan_title',
  change_plan_modal_title: 'change_plan_title',
  cancel_pause_membership: 'cancel_membership_title',
  cancel_membership_confirm: 'cancel_membership_desc',
  keep_benefits: 'keep_membership',
  pause_membership: 'cancel_membership_title',
