  annual_savings_note: 'plan_annual_sub',
  lite_subtext: 'plan_lite_sub',
  join_monthly: 'join_prime_monthly',
  join_annual: 'join_prime_annual',
  join_lite: 'plan_lite_title',
  prime_nav_link: 'prime_nav',
  prime_membership_link: 'your_prime_membership'
