Object.keys(ELECTROMART_PRIME_I18N).forEach((lang) => {
  const dict = ELECTROMART_PRIME_I18N[lang];
  Object.keys(PRIME_ALIAS_MAP).forEach((aliasKey) => {
    const src = PRIME_ALIAS_MAP[aliasKey];
    if (dict[src] && !dict[aliasKey]) {
      dict[aliasKey] = dict[src];
    }
  });
});

// Merge into EM_TRANSLATIONS & TRANSLATIONS for all languages
if (typeof window !== "undefined") {
  if (window.EM_TRANSLATIONS) {
    Object.keys(ELECTROMART_PRIME_I18N).forEach((lang) => {
      if (window.EM_TRANSLATIONS[lang]) {
        Object.assign(window.EM_TRANSLATIONS[lang], ELECTROMART_PRIME_I18N[lang]);
      }
    });
  }
  if (window.TRANSLATIONS) {
    Object.keys(ELECTROMART_PRIME_I18N).forEach((lang) => {
      if (window.TRANSLATIONS[lang]) {
        Object.assign(window.TRANSLATIONS[lang], ELECTROMART_PRIME_I18N[lang]);
      }
    });
  }
}

